#!/usr/bin/env python3
"""
BulwarkOS OOBE Wizard — entry point.
Run with: python3 -m bulwarkos_wizard
"""

import sys
import os
import gi

gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw, Gio
from .wizard_window import WizardWindow

STATE_FILE = "/var/lib/bulwarkos/.setup-complete"


def already_configured() -> bool:
    return os.path.exists(STATE_FILE)


class BulwarkApp(Adw.Application):
    def __init__(self):
        super().__init__(
            application_id="org.bulwarkos.Setup",
            flags=Gio.ApplicationFlags.FLAGS_NONE,
        )
        self.connect("activate", self.on_activate)

    def on_activate(self, app):
        if already_configured():
            # Wizard already ran — exit silently (autostart will have disabled itself)
            print("BulwarkOS setup already completed. Exiting.")
            self.quit()
            return

        win = WizardWindow(application=app)
        win.present()


def main():
    app = BulwarkApp()
    return app.run(sys.argv)


if __name__ == "__main__":
    sys.exit(main())
